+  private registerGlobalErrorObserver(): void {
+    const observer: errorManager.ErrorObserver = {
+      onUnhandledException(errMsg: string): void {
+        hilog.error(DOMAIN, TAG, 'uncaught exception: %{public}s', errMsg);
+      },
+      onException(errObject: Error): void {
+        hilog.error(DOMAIN, TAG, 'uncaught exception name: %{public}s, message: %{public}s, stack: %{public}s',
+          errObject.name, errObject.message, errObject.stack ?? '');
+      }
+    };
+    errorManager.on('error', observer);
+  }
