+  /**
+   * UI 测试桥（arkts-ui-verifier step3，设计 §F）：
+   * 读 want 测试参数写 AppStorage 桥键（__TEST_MODE__ / __TARGET_PAGE__）。
+   * 单页工程零 push（无 NavDestination 子页，__target_page__ 恒为宿主 'Index'）→ 根页桥收敛至 ability 侧：
+   * Index 为 @ComponentV2，模板 §6.2 的 @StorageLink+@Watch（V1 装饰器）不可用，
+   * 既有 loadContent('pages/Index') 即宿主落地，根页零触碰；宿主 target 即写即消费 token。
+   */
+  private consumeTestWant(want: Want): void {
+    const isTestMode: boolean = (want?.parameters?.['__test_mode__'] as boolean) ?? false;
+    AppStorage.setOrCreate<boolean>(TEST_MODE_KEY, isTestMode);
+    if (isTestMode) {
+      // mock 注入钩子（P0001 最小集 = 空，见 TestDataSetup 头注）；fire-and-forget，失败 fail loud
+      TestDataSetup.injectMockData().catch((err: BusinessError) => {
+        hilog.error(DOMAIN, TAG, 'injectMockData failed: %{public}s', JSON.stringify(err));
+      });
+    }
+    const targetPage: string = (want?.parameters?.['__target_page__'] as string) ?? '';
+    if (targetPage.length === 0) {
+      return;
+    }
+    AppStorage.setOrCreate<string>(TARGET_PAGE_KEY, targetPage);
+    // 宿主自挂载特判（模板 §6.2 同语义，收敛 ability 侧）：目标即宿主 → 仅消费 token（幂等重入不重复挂载）
+    if (targetPage === HOST_PAGE_NAME) {
+      AppStorage.setOrCreate<string>(TARGET_PAGE_KEY, '');
+    }
+  }
+
   /** 安全区测量：px → vp（vp = px / densityPixels），写入 WindowModel 4 字段 */
